import{_ as o,V as p,W as c,X as i,Z as n,a1 as s,$ as t,Y as e,F as l}from"./framework-b1bd8911.js";const u={},d=n("h1",{id:"文本转语音",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#文本转语音","aria-hidden":"true"},"#"),s(" 文本转语音")],-1),r=n("blockquote",null,[n("p",null,"输入一段文字，输出一段音频，这就是 TTS（Text To Speech）干的事情")],-1),k=n("p",null,'在开始之前，先定一个小目标：给插件传入"我喜欢吃葡萄 I like to eat grape"和选定的音色，跑完代码，收获一个能直接播放的 mp3 文件。全文就围绕这个目标展开，先讲思路，再手把手带着跑通。',-1),m=n("h2",{id:"i-实现思路",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#i-实现思路","aria-hidden":"true"},"#"),s(" I. 实现思路")],-1),v=n("p",null,[s("文本转语音这件事，听起来很高大上，其实自己从零搞起（收集语料、训练模型、声学合成）是一个天坑，纯 Java 技术玩家基本不会走这条路。更现实的思路是："),n("strong",null,"调用现成的云服务，把文字发过去，把音频流收回来"),s("。")],-1),g={href:"https://github.com/ikfly/java-tts",target:"_blank",rel:"noopener noreferrer"},h=e(`<ol><li>通过 WebSocket 与 Edge 的语音服务建立长连接；</li><li>先发送&quot;输出格式配置&quot;（告诉服务端要 mp3 还是别的格式），再发送 SSML 报文（语音合成标记语言），带上文本、发音人（voice）、语速、音量等参数；</li><li>服务端以二进制帧持续回传音频数据，客户端把音频字节攒起来，收到结束标记后落盘为音频文件。</li></ol><p>quick-media 在这个思路上做了工程化封装：把建连、协议报文、音频流的接收与保存全部收拢，对外只暴露一个链式的 <code>TtsConfig</code> 配置类和一个入口 <code>TtsWrapper</code>，用起来就剩下&quot;传文本、选音色、拿文件&quot;三件事。</p><h2 id="ii-依赖引入" tabindex="-1"><a class="header-anchor" href="#ii-依赖引入" aria-hidden="true">#</a> II. 依赖引入</h2><p>插件对应的 maven 坐标为（以工程 pom 为准）：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>com.github.liuyueyi.media<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>tts-plugin<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>3.1.0<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>需要说明的是，tts-plugin 是 quick-media 后期新增的插件，<strong>可能尚未同步发布到 maven 中央仓库</strong>，直接按上面的坐标依赖有可能拉不到包。如果遇到这种情况，可以按下面两种方式处理。</p></blockquote><p><strong>方式一：jitpack 仓库引入</strong></p><p>quick-media 项目整体在 jitpack 上有发布记录，可以先添加 jitpack 仓库，再依赖（注意 jitpack 方式的 groupId 与中央仓库不同）：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>repositories</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>repository</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>id</span><span class="token punctuation">&gt;</span></span>jitpack.io<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>id</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>url</span><span class="token punctuation">&gt;</span></span>https://jitpack.io<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>url</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>repository</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>repositories</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>com.github.liuyueyi.quick-media<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>tts-plugin<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>3.1.0<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,9),b={href:"https://jitpack.io/#liuyueyi/quick-media",target:"_blank",rel:"noopener noreferrer"},_=e(`<p><strong>方式二：本地源码安装</strong></p><p>最稳妥的方式是把项目拉下来，进入 <code>plugins/tts-plugin</code> 目录执行 <code>mvn clean install</code>，装进本地仓库之后，上面的中央仓库坐标就能正常引用了。</p><p><strong>插件自身的依赖</strong></p><p>从 pom 中可以看到，tts-plugin 依赖了这些东西：<code>base-plugin</code>（quick-media 公共基础包，传递依赖自动引入）、<code>okhttp</code> + <code>okio</code>（WebSocket 长连接和音频字节流的承载）、<code>mp3spi</code>（mp3 解码，用于本地播放）、<code>jflac-codec</code>（flac 解码），以及 scope 为 provided 的 <code>slf4j-api</code> 日志门面（需要项目自己带一个日志实现）。</p><h2 id="iii-使用姿势" tabindex="-1"><a class="header-anchor" href="#iii-使用姿势" aria-hidden="true">#</a> III. 使用姿势</h2><h3 id="_1-最小示例" tabindex="-1"><a class="header-anchor" href="#_1-最小示例" aria-hidden="true">#</a> 1. 最小示例</h3><p>整个插件对外最核心的入口是 <code>TtsWrapper</code>，搭配 <code>TtsConfig</code> 链式配置使用：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">TtsWrapper</span><span class="token punctuation">.</span><span class="token function">sendTxt</span><span class="token punctuation">(</span><span class="token class-name">TtsConfig</span><span class="token punctuation">.</span><span class="token function">newConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">outputFileName</span><span class="token punctuation">(</span><span class="token string">&quot;测试&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">setSsml</span><span class="token punctuation">(</span><span class="token string">&quot;我喜欢吃葡萄 I like to eat grape&quot;</span><span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">voice</span><span class="token punctuation">(</span><span class="token class-name">VoiceEnum</span><span class="token punctuation">.</span>zh_TW_HsiaoChenNeural<span class="token punctuation">)</span>
                <span class="token punctuation">.</span><span class="token function">over</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">TtsWrapper</span><span class="token punctuation">.</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>跑完之后，音频文件就躺在默认目录里了。这段代码的调用链拆开来看：</p><ul><li><code>TtsConfig.newConfig()</code>：创建一个配置实例；<code>outputFileName(&quot;测试&quot;)</code> 指定输出文件名（不带后缀，后缀由输出格式决定）；</li><li><code>setSsml(...)</code>：传入需要转语音的文本，返回 <code>SsmlConfig</code> 对象，接着可以继续配置音色（<code>voice</code>）、语速（<code>rate</code>）、音量（<code>volume</code>）；</li><li><code>over()</code>：回到 <code>TtsConfig</code>，表示 ssml 配置结束；</li><li><code>TtsWrapper.sendTxt(...)</code>：发起合成请求，<code>TtsWrapper.close()</code> 用完之后关闭长连接释放资源。</li></ul><p>音频默认保存路径与操作系统有关（源码 <code>TtsWrapper</code> 中写死的逻辑）：Windows 下是 <code>c://</code>，其他系统是 <code>/tmp</code>。如果想换地方，可以：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 单例初始化时指定</span>
<span class="token class-name">TtsWrapper</span><span class="token punctuation">.</span><span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token string">&quot;/Users/yihui/Desktop&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">getTts</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">sendTxt</span><span class="token punctuation">(</span>config<span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 或者直接更新全局默认路径</span>
<span class="token class-name">TtsWrapper</span><span class="token punctuation">.</span><span class="token function">getInstance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">updateBaseDir</span><span class="token punctuation">(</span><span class="token string">&quot;/Users/yihui/Desktop&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>另外 <code>outputFileName</code> 也支持带路径的写法（如 <code>/tmp/music/测试</code>），子目录不存在时会自动创建。</p><h3 id="_2-完整参数配置" tabindex="-1"><a class="header-anchor" href="#_2-完整参数配置" aria-hidden="true">#</a> 2. 完整参数配置</h3><p>一个把常用参数都配齐的示例（来自工程测试类 <code>Main#testTts</code> 的扩展版）：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">TtsConfig</span> config <span class="token operator">=</span> <span class="token class-name">TtsConfig</span><span class="token punctuation">.</span><span class="token function">newConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token comment">// 输出文件名，不传时会取文本前5个字符 + 时间戳自动生成</span>
        <span class="token punctuation">.</span><span class="token function">outputFileName</span><span class="token punctuation">(</span><span class="token string">&quot;东北话测试&quot;</span><span class="token punctuation">)</span>
        <span class="token comment">// 输出格式，不传默认 audio_24khz_48kbitrate_mono_mp3</span>
        <span class="token punctuation">.</span><span class="token function">outputFormat</span><span class="token punctuation">(</span><span class="token class-name">OutputFormatEnum</span><span class="token punctuation">.</span>audio_24khz_48kbitrate_mono_mp3<span class="token punctuation">)</span>
        <span class="token comment">// 待转换的文本</span>
        <span class="token punctuation">.</span><span class="token function">setSsml</span><span class="token punctuation">(</span><span class="token string">&quot;老铁们，双击666&quot;</span><span class="token punctuation">)</span>
        <span class="token comment">// 音色：东北妹子晓北</span>
        <span class="token punctuation">.</span><span class="token function">voice</span><span class="token punctuation">(</span><span class="token class-name">VoiceEnum</span><span class="token punctuation">.</span>zh_CN_liaoning_XiaobeiNeural<span class="token punctuation">)</span>
        <span class="token comment">// 语速：相对值，+50% 表示比默认快一半；也可以传相对数字如 2</span>
        <span class="token punctuation">.</span><span class="token function">rate</span><span class="token punctuation">(</span><span class="token string">&quot;+50%&quot;</span><span class="token punctuation">)</span>
        <span class="token comment">// 音量：相对值，如 +20%、-10%；绝对值 0.0 ~ 100.0 也支持</span>
        <span class="token punctuation">.</span><span class="token function">volume</span><span class="token punctuation">(</span><span class="token string">&quot;+20%&quot;</span><span class="token punctuation">)</span>
        <span class="token comment">// 结束 ssml 配置</span>
        <span class="token punctuation">.</span><span class="token function">over</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token comment">// 合成完成后直接播放</span>
        <span class="token punctuation">.</span><span class="token function">usePlayer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name">TtsWrapper</span><span class="token punctuation">.</span><span class="token function">sendTxt</span><span class="token punctuation">(</span>config<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">TtsWrapper</span><span class="token punctuation">.</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>上面这段代码会合成一段略带东北口音、语速偏快、声音略大的 mp3，并直接播放出来。</p><h3 id="_3-用流的方式保存" tabindex="-1"><a class="header-anchor" href="#_3-用流的方式保存" aria-hidden="true">#</a> 3. 用流的方式保存</h3><p>默认行为是把音频写到文件。如果希望拿到 <code>InputStream</code> 自己处理（比如直接返回给 http 响应、上传到 OSS），可以通过 <code>saveHook</code> 自定义保存逻辑：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">TtsConfig</span> config <span class="token operator">=</span> <span class="token class-name">TtsConfig</span><span class="token punctuation">.</span><span class="token function">newConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">saveHook</span><span class="token punctuation">(</span><span class="token punctuation">(</span>b<span class="token punctuation">,</span> s<span class="token punctuation">,</span> t<span class="token punctuation">)</span> <span class="token operator">-&gt;</span> <span class="token punctuation">{</span>
            <span class="token comment">// b: 音频字节流(ByteString)  s: 保存文件名  t: 文件后缀</span>
            <span class="token class-name">InputStream</span> stream <span class="token operator">=</span> <span class="token class-name">StreamSaveHook</span><span class="token punctuation">.</span><span class="token function">save</span><span class="token punctuation">(</span>b<span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token comment">// 拿到流之后想干嘛就干嘛，这里以保存文件为例</span>
            <span class="token class-name">FileWriteUtil</span><span class="token punctuation">.</span><span class="token function">saveFileByStream</span><span class="token punctuation">(</span>stream<span class="token punctuation">,</span> <span class="token string">&quot;mp3&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token keyword">return</span> <span class="token keyword">null</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">setSsml</span><span class="token punctuation">(</span><span class="token string">&quot;飞流直下三千尺 疑是银河落九天&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">voice</span><span class="token punctuation">(</span><span class="token class-name">VoiceEnum</span><span class="token punctuation">.</span>zh_CN_liaoning_XiaobeiNeural<span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">over</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name">TtsWrapper</span><span class="token punctuation">.</span><span class="token function">sendTxt</span><span class="token punctuation">(</span>config<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">TtsWrapper</span><span class="token punctuation">.</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>saveHook</code> 是一个函数式接口 <code>OutputSaveHook&lt;T&gt;</code>，入参为音频字节、文件名、后缀，返回值会被原样传递；不设置时默认走 <code>FileSaveHook</code>，保存为本地文件并返回绝对路径。</p><h2 id="iv-参数说明" tabindex="-1"><a class="header-anchor" href="#iv-参数说明" aria-hidden="true">#</a> IV. 参数说明</h2><h3 id="_1-音色选择-voiceenum" tabindex="-1"><a class="header-anchor" href="#_1-音色选择-voiceenum" aria-hidden="true">#</a> 1. 音色选择（VoiceEnum）</h3><p>音色是 TTS 里最有意思的参数。<code>VoiceEnum</code> 枚举内置了 300+ 个发音人，全部来自 Edge 语音服务的音色列表，覆盖了几十种语言，几个有代表性的：| 枚举值 | 说明 | | :-: | :-: | | zh_CN_XiaoxiaoNeural | 晓晓，中文女声，<strong>默认音色</strong>，活泼温暖 | | zh_CN_YunxiNeural | 云希，中文男声，活泼阳光 | | zh_CN_YunjianNeural | 云健，适合影视和体育解说 | | zh_CN_YunyeNeural | 云野，成熟男声，适合有声书 | | zh_CN_liaoning_XiaobeiNeural | 晓北，东北方言女声 | | zh_CN_shaanxi_XiaoniNeural | 晓妮，陕西方言女声 | | zh_HK_HiuMaanNeural | 曉曼，粤语女声 | | zh_TW_HsiaoChenNeural | 曉臻，台湾女声 | | en_US_AriaNeural | Aria，美式英语女声 |</p><p><code>voice()</code> 支持传枚举，也支持直接传字符串（如 <code>.voice(&quot;zh-CN-YunxiNeural&quot;)</code>，会自动匹配枚举，匹配不到时兜底使用晓晓）。如果想在运行时动态查询有哪些音色，可以借助 <code>LocaleService</code>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">LocaleService</span> service <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">LocaleService</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 按语言前缀查询，如 zh、en、ja</span>
<span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">VoiceEnum</span><span class="token punctuation">&gt;</span></span> zhVoices <span class="token operator">=</span> service<span class="token punctuation">.</span><span class="token function">getVoiceByLan</span><span class="token punctuation">(</span><span class="token string">&quot;zh&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// 按语言地区枚举查询</span>
<span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">VoiceEnum</span><span class="token punctuation">&gt;</span></span> cantonese <span class="token operator">=</span> service<span class="token punctuation">.</span><span class="token function">getVoiceByLocale</span><span class="token punctuation">(</span><span class="token class-name">LocaleEnum</span><span class="token punctuation">.</span>zh_HK<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>完整的音色清单，建议直接翻 <code>VoiceEnum</code> 源码，每个枚举值上都带了中文注释（性别、声音特点、适合场景）。此外插件还内置了 <code>LocaleEnum</code>（语言地区枚举，如 <code>zh_CN</code>、<code>zh_HK</code>、<code>en_US</code> 等上百个），是 <code>LocaleService</code> 查询音色时的检索维度。</p><h3 id="_2-语速与音量-rate-volume" tabindex="-1"><a class="header-anchor" href="#_2-语速与音量-rate-volume" aria-hidden="true">#</a> 2. 语速与音量（rate / volume）</h3><p><code>SsmlConfig</code> 上的 <code>rate</code> 和 <code>volume</code> 均支持多种写法（参考 Azure 语音服务的 prosody 规范）：</p><ul><li><strong>相对百分比</strong>：<code>+50%</code>、<code>-50%</code>、<code>50%</code>，表示在默认值基础上变化；</li><li><strong>相对数字</strong>：<code>rate</code> 传 <code>2</code> 表示两倍速，<code>0.5</code> 表示一半速；</li><li><strong>绝对值</strong>：<code>volume</code> 支持 <code>0.0 ~ 100.0</code> 的数字，默认 <code>100.0</code>。</li></ul><p>两个参数不设置时的默认值为 <code>+0%</code>，即保持原样。</p><h3 id="_3-输出格式-outputformatenum" tabindex="-1"><a class="header-anchor" href="#_3-输出格式-outputformatenum" aria-hidden="true">#</a> 3. 输出格式（OutputFormatEnum）</h3><p><code>OutputFormatEnum</code> 定义了 Edge 语音服务支持的全部输出格式，包括 mp3、opus、ogg、pcm、webm、amr 等几十种，常用的有：</p><table><thead><tr><th style="text-align:center;">枚举值</th><th style="text-align:center;">说明</th></tr></thead><tbody><tr><td style="text-align:center;">audio_24khz_48kbitrate_mono_mp3</td><td style="text-align:center;"><strong>默认格式</strong>，官方也推荐</td></tr><tr><td style="text-align:center;">audio_16khz_32kbitrate_mono_mp3</td><td style="text-align:center;">低码率 mp3，音质一般但文件小</td></tr><tr><td style="text-align:center;">audio_48khz_192kbitrate_mono_mp3</td><td style="text-align:center;">高采样率高码率，音质更好</td></tr><tr><td style="text-align:center;">raw_16khz_16bit_mono_pcm</td><td style="text-align:center;">裸 pcm 流，方便做二次处理</td></tr></tbody></table><p>一点特别提醒：<strong>输出文件的后缀是从格式名里解析出来的</strong>，比如 <code>audio-24khz-48kbitrate-mono-mp3</code> 解析出 <code>mp3</code>。而内置播放器只认 mp3 和 pcm，选了 opus、ogg 之类的格式就只做文件保存，不要开启 <code>usePlayer()</code>，否则播放环节会报&quot;不支持的音频文件&quot;。</p><h3 id="_4-说话风格-ttsstyleenum" tabindex="-1"><a class="header-anchor" href="#_4-说话风格-ttsstyleenum" aria-hidden="true">#</a> 4. 说话风格（TtsStyleEnum）</h3><p>插件里还预留了一个 <code>TtsStyleEnum</code>，罗列了 Edge 服务支持的说话风格，如 <code>cheerful</code>（愉快）、<code>sad</code>（悲伤）、<code>newscast</code>（新闻播报）、<code>poetry-reading</code>（诗朗诵）、<code>whispering</code>（耳语）等三十多种。</p><p>需要说明的是，当前插件组装 SSML 报文时只消费了音色、语速、音量三个参数，<strong>style 尚未接入配置链路</strong>，这个枚举更多是作为能力参考存在；实在需要的话，可以参考 <code>TtsConfig#toConfig</code> 里的 SSML 模板自行扩展 <code>mstts:express-as</code> 标签。</p><h3 id="_5-代理配置" tabindex="-1"><a class="header-anchor" href="#_5-代理配置" aria-hidden="true">#</a> 5. 代理配置</h3><p>插件与 Edge 语音服务走的是 <code>wss://speech.platform.bing.com</code> 长连接，网络受限的环境下可以配置代理：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// socks 代理，工程测试类 Main 中保留的就是这个示例</span>
<span class="token class-name">TtsConfig</span><span class="token punctuation">.</span><span class="token function">newConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">setProxy</span><span class="token punctuation">(</span><span class="token class-name">Proxy<span class="token punctuation">.</span>Type</span><span class="token punctuation">.</span><span class="token constant">SOCKS</span><span class="token punctuation">,</span> <span class="token string">&quot;127.0.0.1&quot;</span><span class="token punctuation">,</span> <span class="token number">10808</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">// http 代理同理</span>
<span class="token class-name">TtsConfig</span><span class="token punctuation">.</span><span class="token function">newConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">setProxy</span><span class="token punctuation">(</span><span class="token class-name">Proxy<span class="token punctuation">.</span>Type</span><span class="token punctuation">.</span><span class="token constant">HTTP</span><span class="token punctuation">,</span> <span class="token string">&quot;127.0.0.1&quot;</span><span class="token punctuation">,</span> <span class="token number">8888</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>代理不通时合成交互会直接失败，排查问题前可以先确认代理是否可用。</p><h2 id="v-播放器说明" tabindex="-1"><a class="header-anchor" href="#v-播放器说明" aria-hidden="true">#</a> V. 播放器说明</h2><p>如果配置了 <code>usePlayer()</code>，音频文件保存成功后会调用 <code>Player.autoPlay(path)</code>，按文件后缀选择播放器：</p><ul><li><code>.mp3</code> → <code>Mp3Player</code>：借助 <code>mp3spi</code> 的 <code>MpegAudioFileReader</code> 把 mp3 解码为 PCM 音频流，再走播放；</li><li><code>.pcm</code> → <code>PcmPlayer</code>：直接把 PCM 数据写入本机音频输出设备（<code>SourceDataLine</code>）；</li><li>其他后缀 → 抛 <code>TtsException</code>，如上文所说，选 mp3 或 pcm 格式再开启播放最稳。</li></ul><p>这个播放能力主要是为本地调试、demo 演示服务的（跑一下就能听到效果）；服务端场景一般不需要，直接拿文件或流去对接前端 <code>&lt;audio&gt;</code> 标签。</p><h2 id="vi-机制补充" tabindex="-1"><a class="header-anchor" href="#vi-机制补充" aria-hidden="true">#</a> VI. 机制补充</h2><p>最后补充几个使用时容易疑惑的点，都来自源码：</p><ol><li><strong><code>TtsWrapper</code> 是单例</strong>：全局只持有一条 WebSocket 连接，多个请求复用它，效率更高；但 <code>sendTxt</code> 内部会空转等待上一次合成完成，属于串行模型；</li><li><strong>连接自动回收</strong>：超过 5 分钟没有新请求会主动断开长连接，下次调用时再重建；</li><li><strong>文本会做转义</strong>：<code>setSsml</code> 里会把文本中的 <code>&lt;</code>、<code>&gt;</code> 替换为《、》，避免破坏 SSML 报文结构；</li><li><strong>必须调用 <code>close()</code></strong>：程序退出前记得关闭，否则 okhttp 的线程池和连接池不会被释放。</li></ol><h2 id="vii-小结" tabindex="-1"><a class="header-anchor" href="#vii-小结" aria-hidden="true">#</a> VII. 小结</h2><p>一句话总结 tts-plugin 的定位：<strong>它把&quot;调云服务合成语音&quot;这件麻烦事封装成了三行代码</strong>——建连、协议、音频流都藏在 <code>TtsWrapper</code> + <code>TtsConfig</code> 背后，开箱只需要关心文本、音色和保存方式。</p><p>典型应用场景也顺手列几个：有声内容批量生成（文章、小说转音频）、消息通知播报（告警、订单状态语音提醒）、给 video/image 类多媒体产物配音。</p><p><strong>项目地址：</strong></p>`,53),f={href:"https://github.com/liuyueyi/quick-media",target:"_blank",rel:"noopener noreferrer"},x={href:"https://github.com/ikfly/java-tts",target:"_blank",rel:"noopener noreferrer"},y=n("blockquote",null,[n("p",null,[s("更多 quick-media 系列教程，欢迎关注公众号 "),n("code",null,"一灰灰blog")])],-1);function T(q,S){const a=l("ExternalLinkIcon");return p(),c("div",null,[d,r,k,i(" more "),m,v,n("p",null,[s("本插件的核心实现来自开源项目 "),n("a",g,[s("java-tts"),t(a)]),s('，走的就是这条路线——借用 Edge 浏览器"大声朗读"功能背后的语音合成接口：')]),h,n("p",null,[s("jitpack 的版本号以 "),n("a",b,[s("https://jitpack.io/#liuyueyi/quick-media"),t(a)]),s(" 上实际构建出来的为准，若该 artifact 没有对应的构建版本，请使用方式二。")]),_,n("ul",null,[n("li",null,[n("a",f,[s("https://github.com/liuyueyi/quick-media"),t(a)])]),n("li",null,[s("核心实现参考："),n("a",x,[s("https://github.com/ikfly/java-tts"),t(a)])])]),y])}const j=o(u,[["render",T],["__file","01.文本转语音.html.vue"]]);export{j as default};
